import{_ as l,a0 as o,w as d,s as h,ao as t,I as p,x as a,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"回顧一下 Python 3.4 中的枚舉 | LCTT x X-CMD","titleTemplate":false,"description":"回顧一下 Python 3.4 中的枚舉 | LCTT (202105) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"回顧一下 Python 3.4 中的枚舉 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"回顧一下 Python 3.4 中的枚舉 | LCTT (202105) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202105/20210516 Looking back at what Python 3.4 did for enum","title":"回顧一下 Python 3.4 中的枚舉","tag":"202105","desc":""},"relativePath":"202105/20210516 Looking back at what Python 3.4 did for enum.md","filePath":"[post].md"}'),r={name:"202105/20210516 Looking back at what Python 3.4 did for enum.md"};function c(u,s,g,k,b,f){const n=o("Link");return d(),h("div",null,[s[18]||(s[18]=t('<h1 id="回顧一下-python-3-4-中的枚舉" tabindex="-1">回顧一下 Python 3.4 中的枚舉 <a class="header-anchor" href="#回顧一下-python-3-4-中的枚舉" aria-label="Permalink to “回顧一下 Python 3.4 中的枚舉”">​</a></h1><blockquote><p>另外探索一些未被充分利用但仍然有用的 Python 特性。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202105/30/230947j19r2772m12tccrh.jpg" alt=""></p><p>這是 Python 3.x 首發特性系列文章的第五篇。Python 3.4 在 2014 年首次發佈，儘管它已經發布了很長時間，但它引入的許多特性都沒有被充分利用，而且相當酷。下面是其中的三個。</p><h3 id="枚舉" tabindex="-1">枚舉 <a class="header-anchor" href="#枚舉" aria-label="Permalink to “枚舉”">​</a></h3>',5)),p("p",null,[s[1]||(s[1]=a("我最喜歡的邏輯謎題之一是自我描述的 ",-1)),e(n,{href:"https://en.wikipedia.org/wiki/The_Hardest_Logic_Puzzle_Ever"},{default:i(()=>[...s[0]||(s[0]=[a("史上最難的邏輯謎題",-1)])]),_:1}),s[2]||(s[2]=a("。在其中，它談到了三個“神”，他們被稱為 A、B 和 C，他們的身份是真、假和隨機，按一定順序排列。你可以問他們問題，但他們只用神的語言回答，其中 “da” 和 “ja” 表示 “是” 和 “不是”，但你不知道哪個是哪個。",-1))]),s[19]||(s[19]=t(`<p>如果你決定使用 Python 來解決這個問題，你將如何表示神的名字和身份以及神的語言中的詞語？傳統的答案是使用字符串。然而，字符串的拼寫錯誤可能會帶來災難性的後果。</p><p>如果在解題的關鍵部分，你用字符串 “jaa” 而不是 “ja” 進行比較，你就會得到一個錯誤的答案。雖然謎題沒有説明風險是什麼，但這可能是最好的避免方式。</p><p><code>enum</code> 模組讓你能夠以一種可調試但安全的方式來定義這些東西：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import enum</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@enum.unique</span></span>
<span class="line"><span>class Name(enum.Enum):</span></span>
<span class="line"><span>    A = enum.auto()</span></span>
<span class="line"><span>    B = enum.auto()</span></span>
<span class="line"><span>    C = enum.auto()</span></span>
<span class="line"><span>   </span></span>
<span class="line"><span>@enum.unique</span></span>
<span class="line"><span>class Identity(enum.Enum):</span></span>
<span class="line"><span>    RANDOM = enum.auto()</span></span>
<span class="line"><span>    TRUE = enum.auto()</span></span>
<span class="line"><span>    FALSE = enum.auto()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>       </span></span>
<span class="line"><span>@enum.unique</span></span>
<span class="line"><span>class Language(enum.Enum):</span></span>
<span class="line"><span>    ja = enum.auto()</span></span>
<span class="line"><span>    da = enum.auto()</span></span></code></pre></div><p>枚舉的一個好處是，在調試日誌或異常中，枚舉的呈現方式是有幫助的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>name = Name.A</span></span>
<span class="line"><span>identity = Identity.RANDOM</span></span>
<span class="line"><span>answer = Language.da</span></span>
<span class="line"><span>print(&quot;I suspect&quot;, name, &quot;is&quot;, identity, &quot;because they answered&quot;, answer)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    I suspect Name.A is Identity.RANDOM because they answered Language.da</span></span></code></pre></div><h3 id="functools-singledispatch" tabindex="-1">functools.singledispatch <a class="header-anchor" href="#functools-singledispatch" aria-label="Permalink to “functools.singledispatch”">​</a></h3><p>在開發遊戲的“基礎設施”層時，你想通用地處理各種遊戲對象，但仍然允許這些對象自定義動作。為了使這個例子更容易解釋，假設這是一個基於文本的遊戲。當你使用一個對象時，大多數情況下，它只會打印 <code>You are using &lt;x&gt;</code>。但是使用一把特殊的劍可能需要隨機滾動，否則會失敗。</p><p>當你獲得一個物品時，它通常會被添加到庫存中。然而，一塊特別重的石頭會砸碎一個隨機物品。如果發生這種情況，庫存中會失去該物體。</p><p>處理這個問題的一個方法是在物品上設置 <code>use</code> 和 <code>acquire</code> 方法。隨着遊戲複雜性的增加，這些方法會越來越多，使遊戲對象變得難以編寫。</p><p>相反，<code>functools.singledispatch</code> 允許你以安全和尊重命名空間的方式追溯性地添加方法。</p><p>你可以定義沒有行為的類：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>class Torch:</span></span>
<span class="line"><span>    name=&quot;torch&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class Sword:</span></span>
<span class="line"><span>    name=&quot;sword&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>class Rock:</span></span>
<span class="line"><span>    name=&quot;rock&quot;</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import functools</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@functools.singledispatch</span></span>
<span class="line"><span>def use(x):</span></span>
<span class="line"><span>    print(&quot;You use&quot;, x.name)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@functools.singledispatch</span></span>
<span class="line"><span>def acquire(x, inventory):</span></span>
<span class="line"><span>    inventory.add(x)</span></span></code></pre></div><p>對於火炬來説，這些通用的實現已經足夠了：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>inventory = set()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>def deploy(thing):</span></span>
<span class="line"><span>    acquire(thing, inventory)</span></span>
<span class="line"><span>    use(thing)</span></span>
<span class="line"><span>    print(&quot;You have&quot;, [item.name for item in inventory])</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deploy(Torch())</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    You use torch</span></span>
<span class="line"><span>    You have [&#39;torch&#39;]</span></span></code></pre></div><p>然而，劍和石頭需要一些專門的功能：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@use.register(Sword)</span></span>
<span class="line"><span>def use_sword(sword):</span></span>
<span class="line"><span>    print(&quot;You try to use&quot;, sword.name)</span></span>
<span class="line"><span>    if random.random() &lt; 0.9:</span></span>
<span class="line"><span>        print(&quot;You succeed&quot;)</span></span>
<span class="line"><span>    else:</span></span>
<span class="line"><span>        print(&quot;You fail&quot;)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deploy(sword)</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    You try to use sword</span></span>
<span class="line"><span>    You succeed</span></span>
<span class="line"><span>    You have [&#39;sword&#39;, &#39;torch&#39;]</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import random</span></span>
<span class="line"><span></span></span>
<span class="line"><span>@acquire.register(Rock)</span></span>
<span class="line"><span>def acquire_rock(rock, inventory):</span></span>
<span class="line"><span>    to_remove = random.choice(list(inventory))</span></span>
<span class="line"><span>    inventory.remove(to_remove)</span></span>
<span class="line"><span>    inventory.add(rock)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>deploy(Rock())</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>    You use rock</span></span>
<span class="line"><span>    You have [&#39;sword&#39;, &#39;rock&#39;]</span></span></code></pre></div><p>岩石可能壓碎了火炬，但你的代碼更容易閲讀。</p><h3 id="pathlib" tabindex="-1">pathlib <a class="header-anchor" href="#pathlib" aria-label="Permalink to “pathlib”">​</a></h3><p>從一開始，Python 中文件路徑的接口就是“智能字符串操作”。現在，通過 <code>pathlib</code>，Python 有了一種面向對象的方法來操作路徑。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>import pathlib</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>gitconfig = pathlib.Path.home() / &quot;.gitconfig&quot;</span></span>
<span class="line"><span>text = gitconfig.read_text().splitlines()</span></span></code></pre></div><p>誠然，用 <code>/</code> 作為操作符來生成路徑名有點俗氣，但在實踐中卻不錯。像 <code>.read_text()</code> 這樣的方法允許你從小文件中獲取文本，而不需要手動打開和關閉文件句柄。</p><p>這使你可以集中精力處理重要的事情：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>for line in text:</span></span>
<span class="line"><span>    if not line.strip().startswith(&quot;name&quot;):</span></span>
<span class="line"><span>        continue</span></span>
<span class="line"><span>    print(line.split(&quot;=&quot;)[1])</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>     Moshe Zadka</span></span></code></pre></div><h3 id="歡迎來到-2014-年" tabindex="-1">歡迎來到 2014 年 <a class="header-anchor" href="#歡迎來到-2014-年" aria-label="Permalink to “歡迎來到 2014 年”">​</a></h3><p>Python 3.4 大約在七年前就發佈了，但是在這個版本中首次出現的一些功能非常酷，而且沒有得到充分利用。如果你還沒使用，那麼將他們添加到你的工具箱中。</p><hr>`,35)),p("p",null,[s[4]||(s[4]=a("via: ",-1)),e(n,{href:"https://opensource.com/article/21/5/python-34-features"},{default:i(()=>[...s[3]||(s[3]=[a("https://opensource.com/article/21/5/python-34-features",-1)])]),_:1})]),p("p",null,[s[9]||(s[9]=a("作者：",-1)),e(n,{href:"https://opensource.com/users/moshez"},{default:i(()=>[...s[5]||(s[5]=[a("Moshe Zadka",-1)])]),_:1}),s[10]||(s[10]=a(" 選題：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[6]||(s[6]=[a("lujun9972",-1)])]),_:1}),s[11]||(s[11]=a(" 譯者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[7]||(s[7]=[a("geekpi",-1)])]),_:1}),s[12]||(s[12]=a(" 校對：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[15]||(s[15]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[13]||(s[13]=[a("LCTT",-1)])]),_:1}),s[16]||(s[16]=a(" 原創編譯，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[14]||(s[14]=[a("Linux中國",-1)])]),_:1}),s[17]||(s[17]=a(" 榮譽推出",-1))])])}const C=l(r,[["render",c]]);export{v as __pageData,C as default};
